import {b,fmt,clamp,shells,heating,work,buoyancy,pendulum,falling} from '../math.js';
import {C,reflect,read,particles,molecule,atom,cell,neuron,plants,organelles} from '../scene-utils.js';
export default ({g,t,p})=>{let type=p[0];if(type===3)neuron(g,t);else if(type===0){for(let i=0;i<7;i++){g.box((i-3)*.37,0,0,.16,.3,.18,C.green);g.sphere((i-3)*.37,.07,0,.045,C.blue)}}else if(type===1){g.box(0,0,0,1,.7,.5);for(let i=0;i<12;i++)g.sphere(Math.sin(i*7)*.9,Math.cos(i*5)*.6,Math.sin(i*3)*.4,.08,C.pink);g.text(0,.95,0,b('Cells in a matrix','आधात्री में कोशिकाएँ'))}else{for(let i=0;i<4;i++){g.box(0,(i-1.5)*.28,0,1,.1,.15,C.pink);for(let j=0;j<10;j++)g.line([-.9+j*.2,(i-1.5)*.28-.09,0],[-.9+j*.2,(i-1.5)*.28+.09,0],C.white)}}return[{label:b('Tissue family','ऊतक समूह'),value:[b('Epithelial','उपकला'),b('Connective','संयोजी'),b('Muscle','पेशी'),b('Nervous','तंत्रिका')][type]}];};
